function v3_unit(out)
previous_rng=rng; rng_guard=onCleanup(@()rng(previous_rng));
p=vehicle_params;tests={};M=[1 2 0;0 1 3;2 0 1];target=M*[.1;-.2;.3];[u,r]=bounded_control_allocation(M,target,-ones(3,1),ones(3,1));assert(norm(r)<1e-10);tests{end+1}='coupled exact reachable target';
for n=[3 4],rng(82+n);for k=1:15,M=randn(6,n);target=randn(6,1)*3;[u,r]=bounded_control_allocation(M,target,-ones(n,1),ones(n,1));grad=M'*r;free=abs(u)<1-1e-7;assert(all(abs(grad(free))<1e-7));assert(all(grad(u<=-1+1e-7)>=-1e-7));assert(all(grad(u>=1-1e-7)<=1e-7));end;end;tests{end+1}='bounded 3/4 variable KKT including saturation';
c=v3_pid_config(.7,1);x=zeros(10,1);f=[0;0;-20000;100;0;0;zeros(6,1)];[u,z]=v3_pid_step(x,[1;0;0;0],zeros(3,1),f,c,[]);assert(norm(u)<1e-9);for signum=[-1 1],[u,z]=v3_pid_step(x,paper_quat([0;signum*.0001;0]),zeros(3,1),f,c,[]);assert(norm(u(4:7))<1e-3);assert(signum*z.tau_total_request(2)>0);assert(norm(z.tau_a_request+z.tau_cmg_request-z.tau_total_request)<1e-10);end;tests{end+1}='surface first, no needless CMG, torque signs';
x(7:10)=pi/2;for k=1:10,[u,z]=v3_pid_step(x,paper_quat([0;.5;0]),zeros(3,1),f,c,[]);assert(all(isfinite(u)));assert(all(abs(u(4:7))<=p.cmg.gddot_max*.2+1e-9));end;tests{end+1}='near singular bounded command';
x=zeros(10,1);f=[0;0;-20000;100*cosd(3);0;100*sind(3);zeros(6,1)];[u,z]=v3_pid_step(x,[1;0;0;0],zeros(3,1),f,c,[]);assert(norm(z.tau_total_request)<1e-5 && norm(u(4:7))<1e-3,'Natural torque must not be double counted');tests{end+1}='nonzero natural torque cancellation';
f=[0;0;-20000;100;0;0;zeros(6,1)];sat=c;sat.kp=ones(3,1)*1e8;z=[];for k=1:10,[u,z]=v3_pid_step(x,paper_quat([0;.5;0]),zeros(3,1),f,sat,z);end;assert(abs(z.I(2))<1e-12);tests{end+1}='conditional integration under saturation';
a=[];b=[];for k=1:10,[u,a]=v3_pid_step(x,paper_quat([0;.01;0]),zeros(3,1),f,c,a);[v,b]=v3_pid_step(x,-paper_quat([0;.01;0]),zeros(3,1),f,c,b);assert(norm(u-v)<1e-10);end;tests{end+1}='repeatability and quaternion sign equivalence';
s=v3_spec;s.duration=10;for H=[5 8 12 16 sum(s.dts)],d=make_paper_grid(s.dts,H);b=v3_reference(s,d);assert(size(b.q_ref,2)==numel(d)+1);end;tests{end+1}='reference derivative consistency and aligned horizon';
t=(0:.001:20)';r=sin(2*pi*.1*t);y=.5*sin(2*pi*.1*t-.3)+.2+.001*t;a=v3_fit_periodic(t,r,y,.1,0);assert(abs(a.gain_ratio-.5)<1e-10 && abs(a.phase_lag_deg-rad2deg(.3))<1e-9);a=v3_fit_periodic(t,r,.2*ones(size(t)),.1,0);assert(a.phase_unreliable);a=v3_fit_periodic(t,r,y+.1*sin(4*pi*.1*t)+.03*cos(6*pi*.1*t),.1,0);assert(abs(a.harmonic2_deg-.1)<1e-10 && abs(a.harmonic3_deg-.03)<1e-10);tests{end+1}='synthetic UNIT ONLY: known gain, positive lag, harmonics and zero-response phase flag';
assert(v3_period_matches((0:.02:1)',.02));assert(v3_period_matches([0;.02;.04;.047],.02));assert(~v3_period_matches([0;.02;.027;.04],.02));tests{end+1}='sample-clock audit permits only a terminal partial interval';
paper_json(fullfile(out,'unit_tests.json'),struct('passed',true,'tests',{tests}));fprintf('V3_UNIT_PASS %d\n',numel(tests));
end
